import { Component, Inject, Input, Optional, ViewChild } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatSelectModule } from '@angular/material/select';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { TranscriptService } from '../../../services/transcript/transcript.service';
import { FormsModule } from '@angular/forms';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
@Component({
  selector: 'app-publish',
  standalone: true,
  imports: [ButtonComponent, MatSelectModule, FormsModule, MatMenuModule],
  templateUrl: './publish.component.html',
  styleUrl: './publish.component.scss'
})
export class PublishComponent {
  @ViewChild('menuTrigger') menuTrigger: MatMenuTrigger;
  nCaseid: string;
  nSesid: string;
  cTransid: string;
  cPath: string;
  isIgnoreErr: boolean = false;
  isLoading: boolean = false;
  errorCount: number = 10; // Placeholder for error count, adjust as needed
  constructor(private dialogRef: MatDialogRef<PublishComponent>, private transcriptS: TranscriptService,
    @Optional() @Inject(MAT_DIALOG_DATA) public data: { cTransid: string, cPath: string },
  ) {
    this.cTransid = data.cTransid;
    this.nCaseid = null;
    this.nSesid = null;
    this.cPath = data.cPath;

  }

  cases: any = [
    { name: 'case 1' },
    { name: 'case 2' },
    { name: 'case 3' }
  ]
  sessions: any = [
    { name: 'Session 1' },
    { name: 'session 2' },
    { name: 'session 3' }
  ]


  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.getCaseCombo()

  }
  async getCaseCombo() {
    this.cases = await this.transcriptS.getCaseCombo();
  }

  async getSessionCombo() {
    debugger;
    this.nSesid = null;
    if (this.nCaseid) {
      this.sessions = await this.transcriptS.getSessionCombo(this.nCaseid);
    } else {
      this.sessions = [];
    }
  }

  close() {
    this.dialogRef.close();
  }

  async publish(isIgnoreErr?: boolean) {
    this.isLoading = true;
    const publishRequest = {
      cTransid: this.cTransid,
      nCaseid: this.nCaseid,
      nSesid: this.nSesid,
      cPath: this.cPath,
      isIgnoreErr: isIgnoreErr,
      errorCount: this.errorCount // This is a placeholder, replace with actual error count logic if needed
    }
    const res = await this.transcriptS.publishTranscript(publishRequest);
    this.isLoading= false;
    if (res && res.msg == 1) {
      this.dialogRef.close(res);
    } if (res && res.msg == -1 && res.isIgnoreErr) {
      this.menuTrigger.openMenu();
      this.isIgnoreErr = res.isIgnoreErr ? true : false;
    }

  }
}
