import { Component } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ProgressComponent } from '../../../../shared/components/progress/progress.component';
import { MatDialogRef } from '@angular/material/dialog';
import { UploadManagementService } from '../../../services/upload/upload-management/upload-management.service';
import { fileUploadMDL } from '../../../interfaces/upload.interface';
import { TranscriptService } from '../../../services/transcript/transcript.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-transcript-import',
  standalone: true,
  imports: [FormsModule, ButtonComponent, MatSelectModule, IconComponent, ProgressComponent],
  templateUrl: './transcript-import.component.html',
  styleUrl: './transcript-import.component.scss'
})
export class TranscriptImportComponent {
  isUpload: boolean = false;
  uploadFile: any;
  isImported: boolean = false;
  cFilename: string = '';
  uploadedPath: string = '';
  uploading: boolean = false;
  nLines: number = 22;
  nStartpg: number = 2;
  nSecondpg: number = 3;
  nPages: number = 0;
  isConvert = false;
  reason: string = '';


  constructor(private dialogRef: MatDialogRef<TranscriptImportComponent>, public upload: UploadManagementService, private transcriptS: TranscriptService) { }



  getFile() {
    const fileInput: any = document.querySelector('input[type="file"]');
    fileInput.click();
  }


  closeImport(isImported: boolean) {
    if (isImported) {
      this.dialogRef.close({
        isImported: true,
        fileData: {
          filePath: this.uploadedPath,
          fileName: this.uploadFile.name,
          fileType: this.uploadFile.type,
          nStartpg: this.nStartpg,
          nSecondpg: this.nSecondpg,
          nLines: this.nLines,
          nPages: this.nPages
        }
      });
    } else {
      this.dialogRef.close();
    }
  }

  async onFileChange(e) {
    this.uploadFile = e.target.files[0];
    this.cFilename = this.uploadFile.name;
    this.isUpload = true;
    this.uploadTransFile();
  }

  async uploadTransFile() {
    const formData = new FormData();
    formData.append('rootPath', 'users');
    formData.append('filename', ('transcript_' + new Date().getTime()).toString());
    formData.append('filetype', this.uploadFile.type);
    formData.append('file', this.uploadFile);
    let res: any = await this.transcriptS.transcriptUpload(formData);
    this.uploading = true;
    if (res.msg == -1) {
      this.reason = res.error.message;
      this.isImported = false;
    } else {
      this.uploading = false;
      this.isConvert = false;
      this.uploadedPath = `${res.path}`
      this.convertTextToJSON();
    }
  }

  async convertTextToJSON() {
    this.isConvert = true;
    let res: any = await this.transcriptS.ConvertTextToJSON(this.uploadedPath);
    debugger;
    if (res.msg == -1) {

      this.reason = res.error;
      this.uploading = false;
      this.isConvert = false;
      this.isImported = false;
    } else {
      this.uploading = false;
      this.isConvert = true;
      this.isImported = true
      this.uploadedPath = `${res.path}`
      this.getFileSummery();
    }
  }

  async getFileSummery() {
    let res: any = await this.transcriptS.getFileSummery(this.uploadedPath);
    console.log(res);
    if (res.msg == 1) {
      this.nLines = res.maxLineno;
      this.nStartpg = res.firstPageNo;
      this.nPages = res.totalPages
    }else{  
        
      this.reason = res.error;
      this.uploading = false;
      this.isConvert = false;
      this.isImported = false;
    }
  }




}
