import { Component, OnInit } from '@angular/core';
import { TranscriptTableComponent } from './transcript-table/transcript-table.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { AvatarComponent } from '../../../shared/components/avatar/avatar.component';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { setUserInfo } from '../../../core/interfaces/login.interface';
import { TranscriptImportComponent } from './transcript-import/transcript-import.component';
import { SectionCreationComponent } from '../bundlemanagement/section-creation/section-creation.component';
import { MatDialog } from '@angular/material/dialog';
import { TranscriptPropertiesComponent } from './transcript-properties/transcript-properties.component';
import { TranscriptService } from '../../services/transcript/transcript.service';
@Component({
  selector: 'app-transscript',
  standalone: true,
  imports: [
    CommonModule,
    TranscriptTableComponent,
    ButtonComponent,
    IconComponent,
    AvatarComponent
  ],
  templateUrl: './transscript.component.html',
  styleUrl: './transscript.component.scss'
})
export class TransscriptComponent implements OnInit {
  userDetails: setUserInfo;
  selectedTheme: any = null;
  transcriptForm: any = null;
  fileData: any = null;
  constructor(
    private secureStorage: SecureStorageService,
    private router: Router,
    private dialog: MatDialog, private transcriptS: TranscriptService,
  ) { }

  async ngOnInit() {
    this.userDetails = await this.secureStorage.getUserInfo();
  }

  onSignOut() {
    this.secureStorage.logOut();
    this.router.navigate(['/auth/login']);
  }

  onImportTranscript() {
    // Handle import transcript logic
    console.log('Import transcript clicked');
  }


  importTranscript(cTransid?: string) {
    // this.openTranscriptProperties();
    // return;
    const dialogRef = this.dialog.open(TranscriptImportComponent, {
      width: '900px',
      height: 'fit-content',
      maxHeight: '99vh',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        if (result.isImported) {
          this.fileData = result.fileData;
          this.openTranscriptProperties(cTransid, 'COPY');
        }
      }
    })
  }


  openTranscriptProperties(cTransid?: string, action?: string) {
    const dialogRef = this.dialog.open(TranscriptPropertiesComponent, {
      width: '1400px',
      maxWidth: '99vw',
      height: 'fit-content',
      maxHeight: '95vh',
      panelClass: ['transcript-properties-dialog', 'overflow-hidden'],
      data: {
        fileData: this.fileData,
        cTransid: cTransid,
        action: action  // 'COPY' or 'EDIT'
      }
    });
    dialogRef.afterClosed().subscribe(result => {
      // if (result) {
        this.selectedTheme = Math.floor(100000 + Math.random() * 900000) //rundom number
      //   console.log('Received from properties:', result);
      // }
    })
  }

  tableEvent(event: any) {
    if (event.event === 'edit') {
      this.openTranscriptProperties(event.data.cTransid);
    } else if (event.event === 'COPY') {
      this.importTranscript(event.data.cTransid);
    }
  }


}
